use crate::{host_tools::HostToolRuntime, mcp_state::McpState, memory_store::JsonMemoryStore};
use rakazo_core::{Agent, AgentExecutor, AgentRuntime, ExecutionInput, ExecutorError, MemoryRecord, MemoryStore, ModelMessage, ModelProvider, RuntimeSnapshot, StreamCallback, Task, TaskId, ToolCall, ToolExecutor, ToolRegistry, ToolResult, ToolRisk, ToolDefinition, ToolRuntime, WorkspaceFs, ApprovalGate};
use rakazo_model_openai::OpenAiCompatibleProvider;
use std::{path::Path, sync::Arc};
struct HostToolExecutor{workspace:Arc<ToolRuntime>,host:HostToolRuntime,mcp:McpState,memory:Arc<JsonMemoryStore>,agent_id:rakazo_core::AgentId}
impl ToolExecutor for HostToolExecutor{fn execute(&self,call:&ToolCall)->Result<ToolResult,ExecutorError>{if call.name.starts_with("filesystem."){return self.workspace.execute(call).map_err(|e|ExecutorError::Tool(e.to_string()));}if call.name=="memory.remember"{let content=call.arguments.get("content").and_then(|v|v.as_str()).ok_or_else(||ExecutorError::Tool("memory.remember requires content".into()))?;self.memory.remember(MemoryRecord::new(self.agent_id,content)).map_err(|e|ExecutorError::Tool(e.to_string()))?;return Ok(ToolResult{success:true,output:serde_json::json!({"ok":true})});}if call.name.starts_with("host."){return self.host.execute(call);}if call.name=="mcp.call_tool"{let server=call.arguments.get("serverId").and_then(|v|v.as_str()).ok_or_else(||ExecutorError::Tool("mcp.call_tool requires serverId".into()))?;let name=call.arguments.get("tool").and_then(|v|v.as_str()).ok_or_else(||ExecutorError::Tool("mcp.call_tool requires tool".into()))?;let args=call.arguments.get("arguments").cloned().unwrap_or_else(||serde_json::json!({}));let output=self.mcp.call_tool(server,name,args).map_err(ExecutorError::Tool)?;return Ok(ToolResult{success:true,output});}crate::computer_bridge::execute(call.clone()).map(|value|serde_json::from_value(value).unwrap_or(ToolResult{success:false,output:serde_json::json!({"error":"invalid computer tool response"})})).map_err(ExecutorError::Tool)}}
pub struct AgentExecutionResult{pub task_id:TaskId,pub content:String,pub tool_calls:usize,pub completed:bool,pub snapshot:RuntimeSnapshot}
pub fn execute_with_runtime(provider:&dyn ModelProvider,runtime:AgentRuntime,agent_id:rakazo_core::AgentId,task_id:TaskId,model:String,prompt:String,system_prompt:Option<String>,temperature:Option<f32>,max_tokens:Option<u32>,approval:Arc<dyn ApprovalGate>,workspace_root:impl AsRef<Path>,memory_path:impl AsRef<Path>,mcp:McpState,history:Vec<ModelMessage>,stream:Option<StreamCallback>,auto_memory:bool)->Result<AgentExecutionResult,String>{let workspace_fs=Arc::new(WorkspaceFs::new(workspace_root).map_err(|e|e.to_string())?);let mut workspace=ToolRuntime::new();rakazo_core::register_workspace_tools(&mut workspace,workspace_fs);let workspace=Arc::new(workspace);let host=HostToolRuntime::new()?;let mut tools=ToolRegistry::default();rakazo_core::register_computer_automation_definitions(&mut tools).map_err(|e|e.to_string())?;for definition in [ToolDefinition{name:"filesystem.read_file".into(),description:"Read a text file inside the agent workspace.".into(),risk:ToolRisk::ReadOnly,requires_approval:false},ToolDefinition{name:"filesystem.write_file".into(),description:"Write a text file inside the agent workspace.".into(),risk:ToolRisk::Mutating,requires_approval:true},ToolDefinition{name:"filesystem.list_dir".into(),description:"List files inside the agent workspace.".into(),risk:ToolRisk::ReadOnly,requires_approval:false},ToolDefinition{name:"memory.remember".into(),description:"Persist a durable fact or preference about the user for later conversations.".into(),risk:ToolRisk::Mutating,requires_approval:false},ToolDefinition{name:"mcp.call_tool".into(),description:"Call a tool exposed by a connected MCP server. Requires explicit approval.".into(),risk:ToolRisk::Mutating,requires_approval:true}]{tools.register(definition).map_err(|e|e.to_string())?;}HostToolRuntime::register_definitions(&mut tools)?;let memory=Arc::new(JsonMemoryStore::open(memory_path).map_err(|e|e.to_string())?);let host_executor=HostToolExecutor{workspace,host,mcp,memory:memory.clone(),agent_id};let mut executor=AgentExecutor::new(&runtime,provider,&tools,&host_executor,&*approval).with_memory(&*memory).with_history(history);if let Some(callback)=stream{executor=executor.with_stream(callback);}let output=executor.execute(ExecutionInput{task_id,agent_id,model,prompt:prompt.clone(),system_prompt,temperature,max_tokens}).map_err(|e|e.to_string())?;if auto_memory&&output.completed{memory.remember(MemoryRecord::new(agent_id,format!("Task: {prompt}\nResult: {}",output.content))).map_err(|e|e.to_string())?;}let snapshot=runtime.snapshot().map_err(|e|e.to_string())?;Ok(AgentExecutionResult{task_id,content:output.content,tool_calls:output.tool_calls,completed:output.completed,snapshot})}
pub fn new_runtime_task(prompt:String)->Result<(AgentRuntime,rakazo_core::AgentId,Task),String>{let runtime=AgentRuntime::new();let agent=Agent::new("desktop-agent");let agent_id=agent.id;runtime.register_agent(agent).map_err(|e|e.to_string())?;let task=Task::new(agent_id,prompt);Ok((runtime,agent_id,task))}
pub fn provider_from_env()->Result<OpenAiCompatibleProvider,String>{OpenAiCompatibleProvider::from_env().map_err(|e|e.to_string())}
pub fn provider_from_connection(base_url:&str,api_key:&str)->Result<OpenAiCompatibleProvider,String>{OpenAiCompatibleProvider::new(base_url,api_key).map_err(|e|e.to_string())}
